<?php
declare(strict_types=1);

function bottomUpTree(int $depth): array
{
    if ($depth <= 0) {
        return [null, null];
    }
    $depth--;
    return [bottomUpTree($depth), bottomUpTree($depth)];
}

function itemCheck(array $node): int
{
    if ($node[0] === null) {
        return 1;
    }
    return 1 + itemCheck($node[0]) + itemCheck($node[1]);
}

function main(array $argv): void
{
    $n = isset($argv[1]) ? (int)$argv[1] : 0;

    $minDepth = 4;
    $maxDepth = max($minDepth + 2, $n);
    $stretchDepth = $maxDepth + 1;

    $stretchTree = bottomUpTree($stretchDepth);
    echo "stretch tree of depth {$stretchDepth}\t check: " . itemCheck($stretchTree) . "\n";
    unset($stretchTree);

    $longLivedTree = bottomUpTree($maxDepth);

    $out = '';
    for ($depth = $minDepth; $depth <= $maxDepth; $depth += 2) {
        $iterations = 1 << ($maxDepth - $depth + $minDepth);
        $check = 0;
        for ($i = 0; $i < $iterations; $i++) {
            $t = bottomUpTree($depth);
            $check += itemCheck($t);
        }
        $out .= "{$iterations}\t trees of depth {$depth}\t check: {$check}\n";
    }
    echo $out;

    echo "long lived tree of depth {$maxDepth}\t check: " . itemCheck($longLivedTree) . "\n";
}

main($argv);
