            $flips++;
            $k = $perm[0];
        } while ($k != 0);

        if ($flips > $maxFlips) {
            $maxFlips = $flips;
        }
        if ($permCount & 1) {
            $checkSum -= $flips;
        } else {
            $checkSum += $flips;
        }
    }

    // Generate next permutation
